From ddb81b14a6a3b7158f99822ac5f4848218d2c9c5 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Thu, 26 Nov 2026 00:01:35 +0100
Subject: [PATCH] daemon: don't list containers and objects without sensors

allSensors() listed every container and object even when they had no
sensors, so the sensor picker showed empty categories such as Power on a
computer without a battery. Only list them when they contain a sensor.

BUG: 440662
---
 src/daemon.cpp | 16 +++++++++++-----
 1 file changed, 11 insertions(+), 5 deletions(-)

diff --git a/src/daemon.cpp b/src/daemon.cpp
index c0f2f6d..515aecd 100644
--- a/src/daemon.cpp
+++ b/src/daemon.cpp
@@ -136,17 +136,23 @@ KSysGuard::SensorInfoMap Daemon::allSensors() const
 {
     KSysGuard::SensorInfoMap infoMap;
     for (auto c : std::as_const(m_containers)) {
-        auto containerInfo = KSysGuard::SensorInfo{};
-        containerInfo.name = c->name();
-        infoMap.insert(c->id(), containerInfo);
-
         const auto objects = c->objects();
         for(auto object : objects) {
+            const auto sensors = object->sensors();
+            if (sensors.isEmpty()) {
+                continue;
+            }
+
+            if (!infoMap.contains(c->id())) {
+                auto containerInfo = KSysGuard::SensorInfo{};
+                containerInfo.name = c->name();
+                infoMap.insert(c->id(), containerInfo);
+            }
+
             auto objectInfo = KSysGuard::SensorInfo{};
             objectInfo.name = object->name();
             infoMap.insert(object->path(), objectInfo);

-            const auto sensors = object->sensors();
             for (auto sensor : sensors) {
                 infoMap[sensor->path()] = sensor->info();
             }
